<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import {useAuthStore} from '../../stores/auth'
import * as api from '../../api/comparisonAi'
import {savePending,readPending,clearPending} from './comparisonAiState'
const props=defineProps<{comparisonId:string}>(),auth=useAuthStore()
const view=ref<api.ComparisonAiView|null>(null),pending=ref<api.ComparisonAiInput|null>(null),operation=ref<api.ComparisonAiOperation|null>(null)
const busy=ref(false),error=ref(''),missing=ref(false)
let generation=0
const owner=()=>auth.profile?.userId??''
const current=(g:number,u:string,id:string)=>g===generation&&u===owner()&&id===props.comparisonId
const canNew=computed(()=>!!owner()&&!busy.value&&view.value?.configured&&!(operation.value?.state==='RUNNING'&&!operation.value.expired)&&(!pending.value||operation.value?.state==='FAILED'||operation.value?.expired))
const labels={overview:'历史表现',readout:'波动与回撤',risk:'数据与限制'}
function failure(code:string|null){return ({AI_OUTPUT_INVALID:'返回的解释未通过数据核对。',AI_SERVICE_FROZEN:'云端解释服务已暂停。',AI_AUTH_DENIED:'云端拒绝了调用权限。',AI_RATE_LIMITED:'模型调用暂时达到限额。',AI_INTERRUPTED:'上次请求已中断，结果未保存。'} as Record<string,string>)[code??'']??'上次解释未完成。'}
async function apply(op:api.ComparisonAiOperation,g:number,u:string,id:string){if(!current(g,u,id))return;operation.value=op;missing.value=false;if(op.state==='SUCCEEDED'&&op.explanationId){const saved=await api.comparisonAiExplanation(op.explanationId);if(!current(g,u,id))return;view.value={configured:view.value?.configured??false,latest:saved,latestAttempt:op};clearPending(u,id);pending.value=null}else if(op.state==='FAILED'){error.value=failure(op.errorCode)+'原对比结果与已有解释保留。'}}
async function refresh(preserveError=false){if(!owner()||busy.value)return;const g=generation,u=owner(),id=props.comparisonId;busy.value=true;if(!preserveError)error.value='';try{const data=await api.comparisonAiView(id);if(!current(g,u,id))return;view.value=data;if(!pending.value)operation.value=data.latestAttempt}catch(e){if(current(g,u,id))error.value=(e as Error).message}try{const input=pending.value;if(input&&current(g,u,id)){try{await apply(await api.comparisonAiOperation(input.operationId),g,u,id)}catch(e){if(!current(g,u,id))return;if((e as {status?:number}).status===404){missing.value=true;operation.value=null;error.value='尚未找到原解释请求，可以明确重试原请求。'}else error.value='原请求状态未确认，请稍后刷新。'}}}finally{if(current(g,u,id))busy.value=false}}
async function send(input:api.ComparisonAiInput){if(busy.value||!view.value?.configured)return;const g=generation,u=owner(),id=props.comparisonId;busy.value=true;error.value='';try{savePending(u,input);pending.value=input;operation.value=null;missing.value=false;await apply(await api.createComparisonAi(input),g,u,id)}catch(e){if(current(g,u,id))error.value=(e as Error).message+' 请先刷新原请求状态；原结果保留。'}finally{if(current(g,u,id))busy.value=false}}
async function generate(){if(!canNew.value)return;await send({operationId:crypto.randomUUID(),comparisonId:props.comparisonId})}
async function retry(){if(pending.value&&missing.value)await send(pending.value)}
watch(()=>[auth.profile?.userId,props.comparisonId],()=>{generation++;view.value=null;pending.value=null;operation.value=null;busy.value=false;error.value='';missing.value=false;try{if(owner())pending.value=readPending(owner(),props.comparisonId)}catch(e){error.value=(e as Error).message}void refresh(true)},{immediate:true,flush:'sync'})
onBeforeUnmount(()=>generation++)
</script>
<template><section class="comparison-ai" aria-label="AI比较解释" :aria-busy="busy"><div class="heading"><h3>AI比较解释</h3><div class="actions"><button data-refresh :disabled="busy||!auth.profile" @click="refresh()">刷新解释记录</button><button data-generate :disabled="!canNew" @click="generate">{{busy?'正在处理…':operation?.state==='FAILED'||operation?.expired?'重新尝试':'生成AI解释'}}</button></div></div><p class="hint">只解释这份已保存的历史对比。点击生成可能调用模型并产生费用；相同依据可复用已有解释，刷新不会自动生成。</p><p v-if="view&&!view.configured" role="status">多股AI解释暂未启用，指标和已有解释仍可查看。</p><p v-if="error" role="alert">{{error}}</p><div v-if="pending" class="recovery"><p>原请求：{{pending.operationId}}</p><p v-if="operation?.state==='RUNNING'">{{operation.expired?'上次请求已超时，结果未保存；不会自动续费。明确重新尝试可能再次产生费用。':'正在处理，请刷新查看状态。'}}</p><button v-if="missing" data-retry :disabled="busy||!view?.configured" @click="retry">重试原请求</button></div><template v-if="view?.latest"><p class="hint">已保存解释 · {{view.latest.createdAt}} · {{view.latest.context.providerModel}}</p><article v-for="part in view.latest.paragraphs" :key="part.kind"><h4>{{labels[part.kind]}}</h4><p>{{part.text}}</p></article><details><summary>查看解释依据</summary><p>解释编号：{{view.latest.explanationId}}<br>提示词：{{view.latest.context.promptVersion}}<br>公式：{{view.latest.context.formulaVersion}}<br>来源校验：{{view.latest.context.sourceHash}}</p><dl><template v-for="(value,key) in view.latest.context.facts" :key="key"><dt>{{key}}</dt><dd>{{value}}</dd></template></dl></details></template><p v-else-if="view&&!busy" class="hint">还没有这份对比的AI解释。</p></section></template>
<style scoped>.comparison-ai{border-top:1px solid var(--border);margin-top:24px;padding-top:24px}.heading,.actions{display:flex;gap:12px;justify-content:space-between;align-items:center;flex-wrap:wrap}h3{margin:0;font-size:20px}h4{margin:0;font-size:16px}.hint,dd{color:var(--muted);font-size:14px}p,dd{line-height:1.8;overflow-wrap:anywhere}article{margin:16px 0;padding:16px;border:1px solid var(--border);border-radius:10px}button{font:inherit;min-height:44px;padding:8px 14px;background:var(--surface);color:var(--accent);border:1px solid var(--border);border-radius:8px;cursor:pointer}button:disabled{opacity:.55;cursor:default}button:focus-visible{outline:2px solid var(--accent);outline-offset:3px}summary{cursor:pointer;min-height:44px}.recovery{font-size:14px}dd{margin:4px 0 16px}details{overflow-wrap:anywhere}@media(max-width:600px){.actions{width:100%}.actions button{flex:1}}</style>
